1	/**
2	 * pyargparse.mjs
3	 *
4	 * A byte-for-byte emulation of CPython 3.12 `argparse` for exactly this parser:
5	 *
6	 *     parser = argparse.ArgumentParser()
7	 *     parser.add_argument('--domain', type=str, required=True)
8	 *     args = parser.parse_args()
9	 *
10	 * The logic below is a direct transliteration of the relevant parts of
11	 * /usr/lib/python3.12/argparse.py (ArgumentParser._parse_known_args,
12	 * _parse_optional, _get_option_tuples, _match_argument, HelpFormatter).
13	 * Behaviour was verified against the frozen reference binary; see
14	 * argparse-findings.md.
15	 *
16	 * Node.js ESM, zero external dependencies.
17	 */
18	
19	import { writeSync } from 'node:fs';
20	
21	// ---------------------------------------------------------------------------
22	// Low-level output helpers
23	// ---------------------------------------------------------------------------
24	
25	/**
26	 * Synchronous, unbuffered write to a file descriptor.
27	 *
28	 * Python writes to sys.stdout/sys.stderr and flushes on exit. `process.exit()`
29	 * in Node can truncate pending asynchronous writes on a pipe, so we bypass the
30	 * stream layer entirely. Non-blocking pipes can raise EAGAIN; retry those.
31	 */
32	function writeFd(fd, text) {
33	  const buf = Buffer.from(text, 'utf8');
34	  let offset = 0;
35	  while (offset < buf.length) {
36	    try {
37	      offset += writeSync(fd, buf, offset, buf.length - offset);
38	    } catch (err) {
39	      if (err.code === 'EAGAIN') continue;
40	      if (err.code === 'EPIPE') return;
41	      throw err;
42	    }
43	  }
44	}
45	
46	// ---------------------------------------------------------------------------
47	// Python helpers
48	// ---------------------------------------------------------------------------
49	
50	/** POSIX os.path.basename: everything after the last '/'. */
51	export function basename(p) {
52	  const i = String(p).lastIndexOf('/');
53	  return i === -1 ? String(p) : String(p).slice(i + 1);
54	}
55	
56	/** Default prog, matching Python's `os.path.basename(sys.argv[0])`. */
57	export function defaultProgName() {
58	  return basename(process.argv[1] ?? '');
59	}
60	
61	/**
62	 * Approximation of Python 3 `repr()` for a str. Only used by the
63	 * "ignored explicit argument %r" error path.
64	 */
65	function pyRepr(s) {
66	  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
67	  let out = quote;
68	  for (const ch of s) {
69	    const cp = ch.codePointAt(0);
70	    if (ch === '\\') out += '\\\\';
71	    else if (ch === quote) out += '\\' + quote;
72	    else if (ch === '\n') out += '\\n';
73	    else if (ch === '\r') out += '\\r';
74	    else if (ch === '\t') out += '\\t';
75	    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
76	    else out += ch;
77	  }
78	  return out + quote;
79	}
80	
81	/**
82	 * shutil.get_terminal_size().columns — COLUMNS env wins when it is a positive
83	 * integer, then the real terminal size, then the (80, 24) fallback.
84	 */
85	function terminalColumns() {
86	  const env = process.env.COLUMNS;
87	  let columns = 0;
88	  if (env !== undefined && /^[ \t\n\r]*[+-]?\d+[ \t\n\r]*$/.test(env)) {
89	    columns = parseInt(env, 10);
90	  }
91	  if (columns <= 0) {
92	    columns = (process.stdout && process.stdout.columns) || 80;
93	  }
94	  return columns;
95	}
96	
97	/**
98	 * textwrap.wrap() with argparse's defaults: collapse whitespace runs, greedy
99	 * fill, break words that are longer than the available width.
100	 */
101	function textWrap(text, width) {
102	  const collapsed = text.replace(/\s+/g, ' ').trim();
103	  if (!collapsed) return [];
104	  const lines = [];
105	  let line = '';
106	  for (let word of collapsed.split(' ')) {
107	    while (word.length > width) {
108	      // break_long_words=True: emit as much of the word as fits
109	      if (line) {
110	        lines.push(line);
111	        line = '';
112	      }
113	      lines.push(word.slice(0, width));
114	      word = word.slice(width);
115	    }
116	    if (!line) line = word;
117	    else if (line.length + 1 + word.length <= width) line += ' ' + word;
118	    else {
119	      lines.push(line);
120	      line = word;
121	    }
122	  }
123	  if (line) lines.push(line);
124	  return lines;
125	}
126	
127	// ---------------------------------------------------------------------------
128	// The parser definition
129	// ---------------------------------------------------------------------------
130	
131	const PREFIX_CHARS = '-';
132	
133	/** argparse's ArgumentParser._negative_number_matcher (3.12). */
134	const NEGATIVE_NUMBER_MATCHER = /^-\d+$|^-\d*\.\d+$/;
135	
136	const HELP_ACTION = {
137	  optionStrings: ['-h', '--help'],
138	  dest: 'help',
139	  nargs: 0,
140	  required: false,
141	  help: 'show this help message and exit',
142	  isHelp: true,
143	};
144	
145	const DOMAIN_ACTION = {
146	  optionStrings: ['--domain'],
147	  dest: 'domain',
148	  nargs: null, // nargs=None => exactly one value
149	  required: true,
150	  help: null,
151	  isHelp: false,
152	};
153	
154	const ACTIONS = [HELP_ACTION, DOMAIN_ACTION];
155	
156	/**
157	 * _option_string_actions. Insertion order matters: it drives the order of the
158	 * candidate list in "ambiguous option: ... could match --help, --domain".
159	 */
160	const OPTION_STRING_ACTIONS = new Map([
161	  ['-h', HELP_ACTION],
162	  ['--help', HELP_ACTION],
163	  ['--domain', DOMAIN_ACTION],
164	]);
165	
166	/**
167	 * _has_negative_number_optionals: true when any option string itself looks
168	 * like a negative number. None of '-h', '--help', '--domain' does, so a token
169	 * such as "-5" is accepted as a value rather than read as an option.
170	 */
171	const HAS_NEGATIVE_NUMBER_OPTIONALS = ACTIONS.some((a) =>
172	  a.optionStrings.some((s) => NEGATIVE_NUMBER_MATCHER.test(s)),
173	);
174	
175	/** argparse._get_action_name */
176	function actionName(action) {
177	  return action.optionStrings.join('/');
178	}
179	
180	/** HelpFormatter._get_default_metavar_for_optional */
181	function metavarFor(action) {
182	  return action.dest.toUpperCase();
183	}
184	
185	/** ArgumentError: "argument <name>: <message>" */
186	class ArgumentError extends Error {
187	  constructor(action, message) {
188	    super(`argument ${actionName(action)}: ${message}`);
189	    this.name = 'ArgumentError';
190	  }
191	}
192	
193	/** Thrown internally to unwind to the top-level exit handler. */
194	class ExitSignal extends Error {
195	  constructor(code) {
196	    super(`exit ${code}`);
197	    this.code = code;
198	  }
199	}
200	
201	// ---------------------------------------------------------------------------
202	// Help / usage formatting (HelpFormatter)
203	// ---------------------------------------------------------------------------
204	
205	const INDENT_INCREMENT = 2;
206	const DEFAULT_MAX_HELP_POSITION = 24;
207	
208	/** HelpFormatter._format_actions_usage, specialised to our optionals. */
209	function formatActionsUsage(actions) {
210	  const parts = [];
211	  for (const action of actions) {
212	    let part;
213	    if (action.nargs === 0) {
214	      part = action.optionStrings[0];
215	    } else {
216	      part = `${action.optionStrings[0]} ${metavarFor(action)}`;
217	    }
218	    if (!action.required) part = `[${part}]`;
219	    parts.push(part);
220	  }
221	  return parts.join(' ');
222	}
223	
224	/**
225	 * HelpFormatter._format_usage, including the long-prog wrapping branch.
226	 * Returns the usage block *with* its trailing "\n\n".
227	 */
228	export function formatUsageBlock(prog, width = terminalColumns() - 2) {
229	  const prefix = 'usage: ';
230	  const optionals = ACTIONS.filter((a) => a.optionStrings.length);
231	  const positionals = [];
232	  const actionUsage = formatActionsUsage([...optionals, ...positionals]);
233	  let usage = [prog, actionUsage].filter((s) => s).join(' ');
234	
235	  const textWidth = width; // _current_indent is 0 here
236	  if (prefix.length + usage.length > textWidth) {
237	    const partRegexp = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
238	    const optUsage = formatActionsUsage(optionals);
239	    const posUsage = formatActionsUsage(positionals);
240	    const optParts = optUsage.match(partRegexp) ?? [];
241	    const posParts = posUsage.match(partRegexp) ?? [];
242	
243	    const getLines = (parts, indent, linePrefix) => {
244	      const lines = [];
245	      let line = [];
246	      const indentLength = indent.length;
247	      let lineLen = (linePrefix !== undefined ? linePrefix.length : indentLength) - 1;
248	      for (const part of parts) {
249	        if (lineLen + 1 + part.length > textWidth && line.length) {
250	          lines.push(indent + line.join(' '));
251	          line = [];
252	          lineLen = indentLength - 1;
253	        }
254	        line.push(part);
255	        lineLen += part.length + 1;
256	      }
257	      if (line.length) lines.push(indent + line.join(' '));
258	      if (linePrefix !== undefined && lines.length) lines[0] = lines[0].slice(indentLength);
259	      return lines;
260	    };
261	
262	    let lines;
263	    if (prefix.length + prog.length <= 0.75 * textWidth) {
264	      const indent = ' '.repeat(prefix.length + prog.length + 1);
265	      if (optParts.length) {
266	        lines = getLines([prog, ...optParts], indent, prefix);
267	        lines.push(...getLines(posParts, indent));
268	      } else if (posParts.length) {
269	        lines = getLines([prog, ...posParts], indent, prefix);
270	      } else {
271	        lines = [prog];
272	      }
273	    } else {
274	      const indent = ' '.repeat(prefix.length);
275	      lines = getLines([...optParts, ...posParts], indent);
276	      if (lines.length > 1) {
277	        lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
278	      }
279	      lines = [prog, ...lines];
280	    }
281	    usage = lines.join('\n');
282	  }
283	  return `${prefix}${usage}\n\n`;
284	}
285	
286	/** parser.format_usage() — the usage block trimmed to a single trailing "\n". */
287	export function formatUsage(prog = defaultProgName(), width = terminalColumns() - 2) {
288	  return formatUsageBlock(prog, width).replace(/\n+$/, '\n');
289	}
290	
291	/** HelpFormatter._format_action_invocation */
292	function formatActionInvocation(action) {
293	  if (action.nargs === 0) return action.optionStrings.join(', ');
294	  const args = metavarFor(action);
295	  return action.optionStrings.map((s) => `${s} ${args}`).join(', ');
296	}
297	
298	/** parser.format_help() */
299	export function formatHelp(prog = defaultProgName(), width = terminalColumns() - 2) {
300	  // HelpFormatter.__init__
301	  const maxHelpPosition = Math.min(
302	    DEFAULT_MAX_HELP_POSITION,
303	    Math.max(width - 20, INDENT_INCREMENT * 2),
304	  );
305	
306	  // formatter.add_arguments() records the widest invocation, at indent 2.
307	  const visible = ACTIONS; // no help=SUPPRESS actions here
308	  let actionMaxLength = 0;
309	  for (const action of visible) {
310	    actionMaxLength = Math.max(
311	      actionMaxLength,
312	      formatActionInvocation(action).length + INDENT_INCREMENT,
313	    );
314	  }
315	
316	  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
317	  const helpWidth = Math.max(width - helpPosition, 11);
318	  const actionWidth = helpPosition - INDENT_INCREMENT - 2;
319	
320	  // HelpFormatter._format_action
321	  let items = '';
322	  for (const action of visible) {
323	    const invocation = formatActionInvocation(action);
324	    let header;
325	    let indentFirst = 0;
326	    if (!action.help) {
327	      header = ' '.repeat(INDENT_INCREMENT) + invocation + '\n';
328	    } else if (invocation.length <= actionWidth) {
329	      header = ' '.repeat(INDENT_INCREMENT) + invocation.padEnd(actionWidth) + '  ';
330	      indentFirst = 0;
331	    } else {
332	      header = ' '.repeat(INDENT_INCREMENT) + invocation + '\n';
333	      indentFirst = helpPosition;
334	    }
335	
336	    let part = header;
337	    if (action.help && action.help.trim()) {
338	      const helpLines = textWrap(action.help, helpWidth);
339	      if (helpLines.length) {
340	        part += ' '.repeat(indentFirst) + helpLines[0] + '\n';
341	        for (const line of helpLines.slice(1)) {
342	          part += ' '.repeat(helpPosition) + line + '\n';
343	        }
344	      }
345	    } else if (!part.endsWith('\n')) {
346	      part += '\n';
347	    }
348	    items += part;
349	  }
350	
351	  // _Section.format_help for the two action groups. The "positional
352	  // arguments" group is empty, so it contributes nothing.
353	  const optionsSection = '\n' + 'options:\n' + items + '\n';
354	
355	  let help = formatUsageBlock(prog, width) + optionsSection;
356	  // HelpFormatter.format_help: collapse 3+ newlines, then normalise the ends.
357	  help = help.replace(/\n\n\n+/g, '\n\n');
358	  help = help.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
359	  return help;
360	}
361	
362	// ---------------------------------------------------------------------------
363	// The parser
364	// ---------------------------------------------------------------------------
365	
366	/**
367	 * Emulates:
368	 *     parser = argparse.ArgumentParser()
369	 *     parser.add_argument('--domain', type=str, required=True)
370	 *     args = parser.parse_args()
371	 *
372	 * @param {string[]} argv  e.g. process.argv.slice(2)
373	 * @param {string} [progName] defaults to basename(process.argv[1])
374	 * @returns {{domain: string}}
375	 *
376	 * Writes usage/errors itself and terminates the process on -h/--help (exit 0)
377	 * or on any parse error (exit 2), exactly like Python.
378	 */
379	export function parseArgs(argv, progName = defaultProgName()) {
380	  const prog = progName;
381	  const width = terminalColumns() - 2;
382	
383	  const printUsageToStderr = () => writeFd(2, formatUsage(prog, width));
384	
385	  /** ArgumentParser.error() */
386	  const error = (message) => {
387	    printUsageToStderr();
388	    writeFd(2, `${prog}: error: ${message}\n`);
389	    throw new ExitSignal(2);
390	  };
391	
392	  try {
393	    return doParse(argv, prog, width, error);
394	  } catch (err) {
395	    if (err instanceof ExitSignal) {
396	      process.exit(err.code);
397	    }
398	    throw err;
399	  }
400	}
401	
402	function doParse(argv, prog, width, error) {
403	  const argStrings = Array.from(argv, (a) => String(a));
404	  const namespace = { domain: null }; // action defaults; -h has dest SUPPRESS
405	
406	  // -- ArgumentParser._parse_optional ---------------------------------------
407	  function parseOptional(argString) {
408	    if (argString === '') return null;
409	    if (!PREFIX_CHARS.includes(argString[0])) return null;
410	    if (OPTION_STRING_ACTIONS.has(argString)) {
411	      return { action: OPTION_STRING_ACTIONS.get(argString), optionString: argString, sep: null, explicitArg: null };
412	    }
413	    if (argString.length === 1) return null;
414	
415	    // str.partition('=') — split at the FIRST '='
416	    const eq = argString.indexOf('=');
417	    if (eq !== -1) {
418	      const optionString = argString.slice(0, eq);
419	      const explicitArg = argString.slice(eq + 1);
420	      if (OPTION_STRING_ACTIONS.has(optionString)) {
421	        return { action: OPTION_STRING_ACTIONS.get(optionString), optionString, sep: '=', explicitArg };
422	      }
423	    }
424	
425	    const optionTuples = getOptionTuples(argString);
426	    if (optionTuples.length > 1) {
427	      const matches = optionTuples.map((t) => t.optionString).join(', ');
428	      error(`ambiguous option: ${argString} could match ${matches}`);
429	    } else if (optionTuples.length === 1) {
430	      return optionTuples[0];
431	    }
432	
433	    // Looks like a negative number and no option string does => positional.
434	    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !HAS_NEGATIVE_NUMBER_OPTIONALS) {
435	      return null;
436	    }
437	    // Contains a space => positional.
438	    if (argString.includes(' ')) return null;
439	
440	    // Looks like an option, but this parser has no such option.
441	    return { action: null, optionString: argString, sep: null, explicitArg: null };
442	  }
443	
444	  // -- ArgumentParser._get_option_tuples (allow_abbrev=True) ----------------
445	  function getOptionTuples(optionString) {
446	    const result = [];
447	    const c0 = optionString[0];
448	    const c1 = optionString[1];
449	    if (PREFIX_CHARS.includes(c0) && PREFIX_CHARS.includes(c1)) {
450	      // "--..." is only ever split at the '='
451	      const eq = optionString.indexOf('=');
452	      let optionPrefix;
453	      let sep;
454	      let explicitArg;
455	      if (eq === -1) {
456	        optionPrefix = optionString;
457	        sep = null;
458	        explicitArg = null;
459	      } else {
460	        optionPrefix = optionString.slice(0, eq);
461	        sep = '=';
462	        explicitArg = optionString.slice(eq + 1);
463	      }
464	      for (const [candidate, action] of OPTION_STRING_ACTIONS) {
465	        if (candidate.startsWith(optionPrefix)) {
466	          result.push({ action, optionString: candidate, sep, explicitArg });
467	        }
468	      }
469	    } else if (PREFIX_CHARS.includes(c0) && !PREFIX_CHARS.includes(c1)) {
470	      // single-char options may be concatenated with their argument
471	      const optionPrefix = optionString;
472	      const shortOptionPrefix = optionString.slice(0, 2);
473	      const shortExplicitArg = optionString.slice(2);
474	      for (const [candidate, action] of OPTION_STRING_ACTIONS) {
475	        if (candidate === shortOptionPrefix) {
476	          result.push({ action, optionString: candidate, sep: '', explicitArg: shortExplicitArg });
477	        } else if (candidate.startsWith(optionPrefix)) {
478	          result.push({ action, optionString: candidate, sep: null, explicitArg: null });
479	        }
480	      }
481	    }
482	    return result;
483	  }
484	
485	  // -- ArgumentParser._get_nargs_pattern / _match_argument -------------------
486	  function nargsPattern(action) {
487	    let pattern;
488	    if (action.nargs === null) pattern = '(-*A-*)';
489	    else pattern = '(-*' + 'A'.repeat(action.nargs).split('').join('-*') + '-*)';
490	    if (action.optionStrings.length) {
491	      // "-- is not allowed" for optionals
492	      pattern = pattern.split('-*').join('').split('-').join('');
493	    }
494	    return pattern;
495	  }
496	
497	  function matchArgument(action, patternSlice) {
498	    const m = new RegExp('^' + nargsPattern(action)).exec(patternSlice);
499	    if (m === null) {
500	      // nargs=None => "expected one argument"; nargs=0 always matches.
501	      throw new ArgumentError(action, 'expected one argument');
502	    }
503	    return m[1].length;
504	  }
505	
506	  // -- Namespace mutation ----------------------------------------------------
507	  const seenActions = new Set();
508	
509	  /** ArgumentParser._get_values, narrowed to our two actions. */
510	  function getValues(action, args) {
511	    if (args.length === 1 && action.nargs === null) return args[0]; // type=str
512	    return args.slice();
513	  }
514	
515	  function takeAction(action, args) {
516	    seenActions.add(action);
517	    const value = getValues(action, args);
518	    if (action.isHelp) {
519	      writeFd(1, formatHelp(prog, width));
520	      throw new ExitSignal(0);
521	    }
522	    namespace[action.dest] = value;
523	  }
524	
525	  // -- Build the option index and the arg-string pattern ---------------------
526	  const optionStringIndices = new Map();
527	  const patternParts = [];
528	  for (let i = 0; i < argStrings.length; i++) {
529	    if (argStrings[i] === '--') {
530	      // everything after the FIRST '--' is a non-option
531	      patternParts.push('-');
532	      for (let j = i + 1; j < argStrings.length; j++) patternParts.push('A');
533	      break;
534	    }
535	    const tuple = parseOptional(argStrings[i]);
536	    if (tuple === null) {
537	      patternParts.push('A');
538	    } else {
539	      optionStringIndices.set(i, tuple);
540	      patternParts.push('O');
541	    }
542	  }
543	  const argStringsPattern = patternParts.join('');
544	
545	  const extras = [];
546	
547	  // -- ArgumentParser._parse_known_args.consume_optional --------------------
548	  function consumeOptional(startIndex) {
549	    let { action, optionString, sep, explicitArg } = optionStringIndices.get(startIndex);
550	    const actionTuples = [];
551	    let stop;
552	
553	    for (;;) {
554	      if (action === null) {
555	        extras.push(argStrings[startIndex]);
556	        return startIndex + 1;
557	      }
558	
559	      if (explicitArg !== null) {
560	        const argCount = matchArgument(action, 'A');
561	
562	        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
563	          // single-dash option with no argument: try to peel more short options
564	          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
565	            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
566	          }
567	          actionTuples.push([action, []]);
568	          const char = optionString[0];
569	          const nextOptionString = char + explicitArg[0];
570	          if (OPTION_STRING_ACTIONS.has(nextOptionString)) {
571	            optionString = nextOptionString;
572	            action = OPTION_STRING_ACTIONS.get(nextOptionString);
573	            explicitArg = explicitArg.slice(1);
574	            if (explicitArg === '') {
575	              sep = null;
576	              explicitArg = null;
577	            } else if (explicitArg[0] === '=') {
578	              sep = '=';
579	              explicitArg = explicitArg.slice(1);
580	            } else {
581	              sep = '';
582	            }
583	          } else {
584	            extras.push(char + explicitArg);
585	            stop = startIndex + 1;
586	            break;
587	          }
588	        } else if (argCount === 1) {
589	          stop = startIndex + 1;
590	          actionTuples.push([action, [explicitArg]]);
591	          break;
592	        } else {
593	          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
594	        }
595	      } else {
596	        const start = startIndex + 1;
597	        const argCount = matchArgument(action, argStringsPattern.slice(start));
598	        stop = start + argCount;
599	        actionTuples.push([action, argStrings.slice(start, stop)]);
600	        break;
601	      }
602	    }
603	
604	    for (const [a, args] of actionTuples) takeAction(a, args);
605	    return stop;
606	  }
607	
608	  // -- Main consume loop -----------------------------------------------------
609	  // This parser has no positional actions, so consume_positionals() is a no-op
610	  // that always returns start_index unchanged; the branches that depend on it
611	  // making progress are therefore dead and are elided.
612	  try {
613	    const indices = [...optionStringIndices.keys()];
614	    const maxOptionStringIndex = indices.length ? Math.max(...indices) : -1;
615	    let startIndex = 0;
616	    while (startIndex <= maxOptionStringIndex) {
617	      let nextOptionStringIndex = Infinity;
618	      for (const i of indices) {
619	        if (i >= startIndex && i < nextOptionStringIndex) nextOptionStringIndex = i;
620	      }
621	      if (!optionStringIndices.has(startIndex)) {
